import { useState } from 'react';
import { useSnapshotStore } from '../core/SnapshotManager';
import type { RecoverySnapshot } from '../types';

export const TimeTravelDebugger = () => {
  const snapshots = useSnapshotStore((state) => state.snapshots);
  const [selectedSnapshotId, setSelectedSnapshotId] = useState<string | null>(null);
  const [showDiff, setShowDiff] = useState(false);

  const selectedIndex = snapshots.findIndex((s) => s.id === selectedSnapshotId);

  const restoreToSnapshot = (snapshotId: string) => {
    const snapshot = snapshots.find((s) => s.id === snapshotId);
    if (!snapshot) return;

    // Restore form state from this specific snapshot
    const store = useSnapshotStore.getState();
    store.updateForm(snapshot.state.form || snapshot.state);

    store.addLog({
      type: 'recovery',
      message: `⏮️ TIME-TRAVEL: Restored to snapshot from ${new Date(snapshot.timestamp).toLocaleTimeString()}`,
    });
  };

  const calculateDiff = (current: RecoverySnapshot, previous: RecoverySnapshot | null) => {
    if (!previous) return { added: [], modified: [], removed: [] };

    const currentForm = current.state.form || current.state;
    const previousForm = previous.state.form || previous.state;

    const added: string[] = [];
    const modified: string[] = [];
    const removed: string[] = [];

    // Check for added and modified fields
    Object.keys(currentForm).forEach((key) => {
      if (!(key in previousForm)) {
        added.push(key);
      } else if (JSON.stringify((currentForm as any)[key]) !== JSON.stringify((previousForm as any)[key])) {
        modified.push(key);
      }
    });

    // Check for removed fields
    Object.keys(previousForm).forEach((key) => {
      if (!(key in currentForm)) {
        removed.push(key);
      }
    });

    return { added, modified, removed };
  };

  const formatTimestamp = (timestamp: number) => {
    const date = new Date(timestamp);
    return date.toLocaleTimeString('en-US', {
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit'
    });
  };

  const getTimeAgo = (timestamp: number) => {
    const seconds = Math.floor((Date.now() - timestamp) / 1000);
    if (seconds < 60) return `${seconds}s ago`;
    const minutes = Math.floor(seconds / 60);
    if (minutes < 60) return `${minutes}m ago`;
    const hours = Math.floor(minutes / 60);
    return `${hours}h ago`;
  };

  if (snapshots.length === 0) {
    return (
      <div className="bg-white border border-slate-200 shadow-sm rounded-xl p-6">
        <div className="flex items-center space-x-3 mb-4">
          <div className="w-9 h-9 bg-purple-50 border border-purple-100 rounded-lg flex items-center justify-center">
            <div className="text-lg">⏮️</div>
          </div>
          <div>
            <h2 className="text-xl font-bold text-slate-900">Time-Travel Debugger</h2>
            <p className="text-sm text-slate-500">Browse and restore from any snapshot</p>
          </div>
        </div>
        <div className="text-center py-12">
          <div className="text-5xl mb-4">🕐</div>
          <p className="text-slate-600">No snapshots available yet</p>
          <p className="text-sm text-slate-400 mt-1">Fill the form to create snapshots</p>
        </div>
      </div>
    );
  }

  return (
    <div className="bg-white border border-slate-200 shadow-sm rounded-xl p-6">
      {/* Header */}
      <div className="flex items-center justify-between mb-5">
        <div className="flex items-center space-x-3">
          <div className="w-9 h-9 bg-purple-50 border border-purple-100 rounded-lg flex items-center justify-center">
            <div className="text-lg">⏮️</div>
          </div>
          <div>
            <h2 className="text-xl font-bold text-slate-900">Time-Travel Debugger</h2>
            <p className="text-sm text-slate-500">Browse through {snapshots.length} snapshots</p>
          </div>
        </div>
        <button
          onClick={() => setShowDiff(!showDiff)}
          className="bg-purple-50 border border-purple-200 text-purple-700 px-3 py-1 rounded-lg text-sm font-medium hover:bg-purple-100 transition-colors"
        >
          {showDiff ? '📊 Hide Diff' : '📊 Show Diff'}
        </button>
      </div>

      {/* Timeline Slider */}
      <div className="mb-6">
        <div className="flex items-center gap-2 mb-3">
          <span className="text-xs font-semibold text-slate-500 uppercase tracking-wide">
            Timeline
          </span>
          <div className="flex-1 h-px bg-slate-200"></div>
        </div>
        <div className="relative">
          {/* Timeline Bar */}
          <div className="h-2 bg-slate-100 rounded-full relative overflow-hidden">
            <div
              className="absolute h-full bg-gradient-to-r from-purple-400 to-purple-600 rounded-full transition-all"
              style={{ width: `${((selectedIndex + 1) / snapshots.length) * 100}%` }}
            ></div>
          </div>

          {/* Snapshot Markers */}
          <div className="relative h-12 mt-2">
            {snapshots.map((snapshot, index) => {
              const position = (index / (snapshots.length - 1)) * 100;
              const isSelected = snapshot.id === selectedSnapshotId;

              return (
                <button
                  key={snapshot.id}
                  onClick={() => setSelectedSnapshotId(snapshot.id)}
                  className={`absolute transform -translate-x-1/2 transition-all ${
                    isSelected ? 'scale-125' : 'hover:scale-110'
                  }`}
                  style={{ left: `${position}%`, top: '0' }}
                  title={formatTimestamp(snapshot.timestamp)}
                >
                  <div
                    className={`w-3 h-3 rounded-full border-2 ${
                      isSelected
                        ? 'bg-purple-600 border-purple-600'
                        : 'bg-white border-purple-300 hover:border-purple-500'
                    }`}
                  ></div>
                  {isSelected && (
                    <div className="absolute top-5 left-1/2 transform -translate-x-1/2 whitespace-nowrap">
                      <div className="bg-purple-600 text-white text-xs px-2 py-1 rounded shadow-lg">
                        #{index + 1}
                      </div>
                    </div>
                  )}
                </button>
              );
            })}
          </div>
        </div>
      </div>

      {/* Snapshot Grid */}
      <div className="grid grid-cols-1 gap-3 max-h-[400px] overflow-y-auto pr-2 custom-scrollbar">
        {snapshots.map((snapshot, index) => {
          const isSelected = snapshot.id === selectedSnapshotId;
          const previousSnapshot = index > 0 ? snapshots[index - 1] : null;
          const diff = showDiff ? calculateDiff(snapshot, previousSnapshot) : null;
          const formData = snapshot.state.form || snapshot.state;

          return (
            <div
              key={snapshot.id}
              className={`border rounded-lg p-4 transition-all cursor-pointer ${
                isSelected
                  ? 'border-purple-500 bg-purple-50 shadow-md'
                  : 'border-slate-200 hover:border-purple-300 hover:shadow'
              }`}
              onClick={() => setSelectedSnapshotId(snapshot.id)}
            >
              <div className="flex justify-between items-start mb-3">
                <div className="flex items-center gap-2">
                  <span className="text-xs font-bold text-slate-400">#{index + 1}</span>
                  <span className="text-sm font-semibold text-slate-700">
                    {formatTimestamp(snapshot.timestamp)}
                  </span>
                  <span className="text-xs text-slate-400">{getTimeAgo(snapshot.timestamp)}</span>
                </div>
                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    restoreToSnapshot(snapshot.id);
                  }}
                  className="bg-purple-600 hover:bg-purple-700 text-white text-xs px-3 py-1 rounded font-medium transition-colors"
                >
                  ⏮️ Restore
                </button>
              </div>

              {/* Snapshot Data Preview */}
              <div className="bg-white rounded border border-slate-200 p-3 mb-3">
                <div className="text-xs font-mono text-slate-600 space-y-1">
                  {Object.entries(formData).map(([key, value]) => (
                    <div key={key} className="flex gap-2">
                      <span className="text-purple-600 font-semibold">{key}:</span>
                      <span className="text-slate-700 truncate flex-1">
                        {typeof value === 'string'
                          ? value || '(empty)'
                          : JSON.stringify(value)}
                      </span>
                    </div>
                  ))}
                </div>
              </div>

              {/* Diff Display */}
              {showDiff && diff && (
                <div className="space-y-2">
                  {diff.added.length > 0 && (
                    <div className="flex items-center gap-2 text-xs">
                      <span className="bg-emerald-100 text-emerald-700 px-2 py-0.5 rounded font-medium">
                        +{diff.added.length} added
                      </span>
                      <span className="text-slate-500">{diff.added.join(', ')}</span>
                    </div>
                  )}
                  {diff.modified.length > 0 && (
                    <div className="flex items-center gap-2 text-xs">
                      <span className="bg-amber-100 text-amber-700 px-2 py-0.5 rounded font-medium">
                        ~{diff.modified.length} modified
                      </span>
                      <span className="text-slate-500">{diff.modified.join(', ')}</span>
                    </div>
                  )}
                  {diff.removed.length > 0 && (
                    <div className="flex items-center gap-2 text-xs">
                      <span className="bg-red-100 text-red-700 px-2 py-0.5 rounded font-medium">
                        -{diff.removed.length} removed
                      </span>
                      <span className="text-slate-500">{diff.removed.join(', ')}</span>
                    </div>
                  )}
                  {diff.added.length === 0 && diff.modified.length === 0 && diff.removed.length === 0 && (
                    <div className="text-xs text-slate-400">No changes from previous snapshot</div>
                  )}
                </div>
              )}

              {/* State Size */}
              <div className="mt-3 pt-3 border-t border-slate-200 flex justify-between items-center">
                <span className="text-xs text-slate-500">
                  Size: {JSON.stringify(snapshot.state).length} bytes
                </span>
                {isSelected && (
                  <span className="text-xs bg-purple-600 text-white px-2 py-0.5 rounded">
                    Selected
                  </span>
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};
