import { create } from 'zustand';

interface Diagnosis {
  error_id: string;
  root_cause: string;
  confidence: number;
  suggested_fix: string;
  prevention_tips: string[];
  llm_model_used: string;
  timestamp: number;
}

type DiagnosisInput = Omit<Diagnosis, 'timestamp'>;

interface DiagnosisStore {
  diagnoses: Diagnosis[];
  currentDiagnosis: Diagnosis | null;
  loading: boolean;
  addDiagnosis: (diagnosis: DiagnosisInput) => void;
  setCurrentDiagnosis: (diagnosis: DiagnosisInput | null) => void;
  clearDiagnoses: () => void;
  setLoading: (loading: boolean) => void;
}

export const useDiagnosisStore = create<DiagnosisStore>((set) => ({
  diagnoses: [],
  currentDiagnosis: null,
  loading: false,

  addDiagnosis: (diagnosis) => set((state) => ({
    diagnoses: [...state.diagnoses, { ...diagnosis, timestamp: Date.now() }],
    currentDiagnosis: { ...diagnosis, timestamp: Date.now() }
  })),

  setCurrentDiagnosis: (diagnosis) => set({
    currentDiagnosis: diagnosis ? { ...diagnosis, timestamp: Date.now() } : null
  }),

  clearDiagnoses: () => set({
    diagnoses: [],
    currentDiagnosis: null
  }),

  setLoading: (loading) => set({ loading })
}));
