import { create } from 'zustand';
import { useSnapshotStore } from './SnapshotManager';

// BroadcastChannel for cross-tab communication
const CHANNEL_NAME = 'self-healing-sync';

interface TabInfo {
  tabId: string;
  lastHeartbeat: number;
  state: any;
  status: 'active' | 'idle' | 'crashed';
}

interface MultiTabStore {
  currentTabId: string;
  otherTabs: Record<string, TabInfo>;
  channel: BroadcastChannel | null;
  crashedTabs: string[];

  initializeSync: () => void;
  sendHeartbeat: () => void;
  detectDeadTabs: () => void;
  recoverFromTab: (tabId: string) => void;
  cleanup: () => void;
}

// Generate unique tab ID
const generateTabId = () => `tab-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

export const useMultiTabStore = create<MultiTabStore>((set, get) => ({
  currentTabId: generateTabId(),
  otherTabs: {},
  channel: null,
  crashedTabs: [],

  initializeSync: () => {
    // Check if BroadcastChannel is supported
    if (typeof BroadcastChannel === 'undefined') {
      console.warn('BroadcastChannel not supported in this browser');
      return;
    }

    const channel = new BroadcastChannel(CHANNEL_NAME);
    const { currentTabId } = get();

    // Listen for messages from other tabs
    channel.onmessage = (event) => {
      const { type, tabId, state, timestamp } = event.data;

      if (tabId === currentTabId) return; // Ignore own messages

      switch (type) {
        case 'HEARTBEAT':
          // Update other tab's status
          set((prevState) => ({
            otherTabs: {
              ...prevState.otherTabs,
              [tabId]: {
                tabId,
                lastHeartbeat: timestamp,
                state,
                status: 'active',
              },
            },
            // Remove from crashed list if it was there
            crashedTabs: prevState.crashedTabs.filter((id) => id !== tabId),
          }));
          break;

        case 'REQUEST_STATE':
          // Another tab is requesting our state (they just opened)
          get().sendHeartbeat();
          break;

        case 'TAB_CLOSING':
          // Tab is gracefully closing
          set((prevState) => {
            const { [tabId]: removed, ...remainingTabs } = prevState.otherTabs;
            return { otherTabs: remainingTabs };
          });
          break;
      }
    };

    set({ channel });

    // Announce this tab's presence
    channel.postMessage({
      type: 'REQUEST_STATE',
      tabId: currentTabId,
      timestamp: Date.now(),
    });

    // Start heartbeat interval (every 2 seconds)
    const heartbeatInterval = setInterval(() => {
      get().sendHeartbeat();
    }, 2000);

    // Start dead tab detection (every 5 seconds)
    const detectionInterval = setInterval(() => {
      get().detectDeadTabs();
    }, 5000);

    // Cleanup on tab close
    window.addEventListener('beforeunload', () => {
      channel.postMessage({
        type: 'TAB_CLOSING',
        tabId: currentTabId,
        timestamp: Date.now(),
      });
      clearInterval(heartbeatInterval);
      clearInterval(detectionInterval);
    });
  },

  sendHeartbeat: () => {
    const { channel, currentTabId } = get();
    if (!channel) return;

    // Get current form state
    const snapshotStore = useSnapshotStore.getState();
    const currentState = {
      form: snapshotStore.form,
      snapshots: snapshotStore.snapshots,
      recoveryCount: snapshotStore.snapshots.length,
    };

    channel.postMessage({
      type: 'HEARTBEAT',
      tabId: currentTabId,
      state: currentState,
      timestamp: Date.now(),
    });
  },

  detectDeadTabs: () => {
    const now = Date.now();
    const DEAD_THRESHOLD = 10000; // 10 seconds without heartbeat = dead

    const { otherTabs } = get();
    const newCrashedTabs: string[] = [];

    Object.entries(otherTabs).forEach(([tabId, info]) => {
      if (now - info.lastHeartbeat > DEAD_THRESHOLD && info.status === 'active') {
        newCrashedTabs.push(tabId);

        // Mark as crashed
        set((prevState) => ({
          otherTabs: {
            ...prevState.otherTabs,
            [tabId]: { ...info, status: 'crashed' },
          },
        }));

        // Add to crashed list
        set((prevState) => ({
          crashedTabs: [...prevState.crashedTabs, tabId],
        }));

        // Log to recovery timeline
        const snapshotStore = useSnapshotStore.getState();
        snapshotStore.addLog({
          type: 'error',
          message: `🔴 DETECTED: Tab ${tabId.slice(-6)} crashed (no heartbeat for 10s)`,
        });
      }
    });
  },

  recoverFromTab: (tabId: string) => {
    const { otherTabs } = get();
    const crashedTab = otherTabs[tabId];

    if (!crashedTab) {
      console.error('Tab not found:', tabId);
      return;
    }

    // Restore state from crashed tab
    const snapshotStore = useSnapshotStore.getState();

    if (crashedTab.state.form) {
      snapshotStore.updateForm(crashedTab.state.form);

      snapshotStore.addLog({
        type: 'recovery',
        message: `🔄 MULTI-TAB RECOVERY: Restoring state from crashed tab ${tabId.slice(-6)}`,
      });

      // Take a snapshot of recovered state
      snapshotStore.takeSnapshot(crashedTab.state.form);

      snapshotStore.addLog({
        type: 'success',
        message: `✅ RECOVERED: State restored from crashed tab successfully`,
      });
    }

    // Remove from crashed list
    set((prevState) => ({
      crashedTabs: prevState.crashedTabs.filter((id) => id !== tabId),
    }));
  },

  cleanup: () => {
    const { channel, currentTabId } = get();
    if (channel) {
      channel.postMessage({
        type: 'TAB_CLOSING',
        tabId: currentTabId,
        timestamp: Date.now(),
      });
      channel.close();
    }
  },
}));
