import { useEffect, useRef } from 'react';
import { useSnapshotStore } from '../core/SnapshotManager';

export const RecoveryTimeline = () => {
  const logs = useSnapshotStore((state) => state.recoveryLogs);
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    // Scroll only the timeline's own container. Using scrollIntoView here would
    // scroll the whole window down on load because the sentinel sits low on the page.
    const container = scrollContainerRef.current;
    if (container) {
      container.scrollTop = container.scrollHeight;
    }
  }, [logs]);

  const getLogIcon = (type: string) => {
    switch (type) {
      case 'error':
        return '⚠️';
      case 'snapshot':
        return '📸';
      case 'recovery':
        return '🔄';
      case 'success':
        return '✅';
      default:
        return 'ℹ️';
    }
  };

  const getLogColor = (type: string) => {
    switch (type) {
      case 'error':
        return 'border-l-red-500 bg-red-50';
      case 'snapshot':
        return 'border-l-sky-500 bg-sky-50';
      case 'recovery':
        return 'border-l-amber-500 bg-amber-50';
      case 'success':
        return 'border-l-emerald-500 bg-emerald-50';
      default:
        return 'border-l-slate-400 bg-slate-50';
    }
  };

  return (
    <div className="bg-white border border-slate-200 shadow-sm rounded-xl p-6 flex flex-col h-[600px]">
      <div className="flex items-center justify-between mb-5">
        <div className="flex items-center space-x-3">
          <div className="w-9 h-9 bg-indigo-50 border border-indigo-100 rounded-lg flex items-center justify-center">
            <div className="text-lg">⏱️</div>
          </div>
          <div>
            <h2 className="text-xl font-bold text-slate-900">Recovery Timeline</h2>
            <p className="text-sm text-slate-500">Live event log of system recoveries</p>
          </div>
        </div>
        <span className="bg-slate-100 border border-slate-200 text-slate-600 rounded-full px-3 py-1 text-xs font-medium">
          {logs.length} events
        </span>
      </div>

      <div ref={scrollContainerRef} className="flex-1 overflow-y-auto space-y-3 pr-2 custom-scrollbar">
        {logs.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-12">
            <div className="text-5xl mb-4">⏳</div>
            <div className="text-lg font-medium text-slate-600">No recovery events yet</div>
            <p className="text-sm text-slate-400 max-w-xl text-center mt-1">
              Trigger an error using the demo controls to see the self-healing system in action.
              Each recovery event will be logged here with timestamps and recovery metrics.
            </p>
          </div>
        ) : (
          logs.map((log) => (
            <div
              key={log.id}
              className={`flex gap-3 p-3 rounded border-l-4 ${getLogColor(log.type)}`}
            >
              <div className="flex-shrink-0 text-lg">{getLogIcon(log.type)}</div>
              <div className="flex-1">
                <div className="flex justify-between items-start mb-1">
                  <span className="text-sm font-medium text-slate-800">{log.message}</span>
                  {log.recoveryTime && (
                    <span className="text-xs text-emerald-600 font-mono font-semibold">{log.recoveryTime.toFixed(1)}ms</span>
                  )}
                </div>
                {log.errorStack && (
                  <pre className="text-xs text-slate-500 font-mono overflow-x-auto mt-1">
                    {log.errorStack}
                  </pre>
                )}
                <div className="flex gap-3 mt-2 text-xs text-slate-400">
                  {log.stateSize && <span>State: {log.stateSize} bytes</span>}
                  <span>{new Date(log.timestamp).toLocaleTimeString()}</span>
                </div>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};
