import { useEffect, useState } from 'react';
import { useMultiTabStore } from '../core/MultiTabSync';

export const MultiTabMonitor = () => {
  const currentTabId = useMultiTabStore((state) => state.currentTabId);
  const otherTabs = useMultiTabStore((state) => state.otherTabs);
  const crashedTabs = useMultiTabStore((state) => state.crashedTabs);
  const recoverFromTab = useMultiTabStore((state) => state.recoverFromTab);

  const [showRecoveryModal, setShowRecoveryModal] = useState(false);

  useEffect(() => {
    // Show modal when a tab crashes
    if (crashedTabs.length > 0) {
      setShowRecoveryModal(true);
    }
  }, [crashedTabs.length]);

  const handleRecover = (tabId: string) => {
    recoverFromTab(tabId);
    setShowRecoveryModal(false);
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'active':
        return 'bg-emerald-500';
      case 'idle':
        return 'bg-amber-500';
      case 'crashed':
        return 'bg-red-500';
      default:
        return 'bg-slate-500';
    }
  };

  const getTimeAgo = (timestamp: number) => {
    const seconds = Math.floor((Date.now() - timestamp) / 1000);
    if (seconds < 5) return 'just now';
    if (seconds < 60) return `${seconds}s ago`;
    const minutes = Math.floor(seconds / 60);
    return `${minutes}m ago`;
  };

  const otherTabsList = Object.values(otherTabs);

  return (
    <>
      <div className="bg-white border border-slate-200 shadow-sm rounded-xl p-6">
        {/* Header */}
        <div className="flex items-center justify-between mb-5">
          <div className="flex items-center space-x-3">
            <div className="w-9 h-9 bg-blue-50 border border-blue-100 rounded-lg flex items-center justify-center">
              <div className="text-lg">🔗</div>
            </div>
            <div>
              <h2 className="text-xl font-bold text-slate-900">Multi-Tab Monitor</h2>
              <p className="text-sm text-slate-500">
                {otherTabsList.length === 0 ? 'No other tabs detected' : `${otherTabsList.length + 1} tabs active`}
              </p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <span className={`h-2 w-2 rounded-full ${getStatusColor('active')} animate-pulse`}></span>
            <span className="text-sm text-slate-600">Syncing</span>
          </div>
        </div>

        {/* Current Tab */}
        <div className="mb-4">
          <div className="text-xs font-semibold text-slate-500 uppercase tracking-wide mb-2">
            This Tab
          </div>
          <div className="bg-blue-50 border border-blue-200 rounded-lg p-3">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className={`h-3 w-3 rounded-full ${getStatusColor('active')}`}></div>
                <span className="text-sm font-mono text-slate-700">
                  {currentTabId.slice(-8)}
                </span>
                <span className="bg-blue-600 text-white text-xs px-2 py-0.5 rounded font-medium">
                  YOU
                </span>
              </div>
              <span className="text-xs text-slate-500">Broadcasting state</span>
            </div>
          </div>
        </div>

        {/* Other Tabs */}
        {otherTabsList.length > 0 ? (
          <div>
            <div className="text-xs font-semibold text-slate-500 uppercase tracking-wide mb-2">
              Other Tabs
            </div>
            <div className="space-y-2">
              {otherTabsList.map((tab) => (
                <div
                  key={tab.tabId}
                  className={`border rounded-lg p-3 ${
                    tab.status === 'crashed'
                      ? 'border-red-300 bg-red-50'
                      : 'border-slate-200 bg-white'
                  }`}
                >
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                      <div className={`h-3 w-3 rounded-full ${getStatusColor(tab.status)}`}></div>
                      <span className="text-sm font-mono text-slate-700">
                        {tab.tabId.slice(-8)}
                      </span>
                      <span
                        className={`text-xs px-2 py-0.5 rounded font-medium ${
                          tab.status === 'active'
                            ? 'bg-emerald-100 text-emerald-700'
                            : tab.status === 'crashed'
                            ? 'bg-red-100 text-red-700'
                            : 'bg-amber-100 text-amber-700'
                        }`}
                      >
                        {tab.status.toUpperCase()}
                      </span>
                    </div>
                    <div className="flex items-center gap-3">
                      <span className="text-xs text-slate-500">
                        {getTimeAgo(tab.lastHeartbeat)}
                      </span>
                      {tab.status === 'crashed' && (
                        <button
                          onClick={() => handleRecover(tab.tabId)}
                          className="bg-red-600 hover:bg-red-700 text-white text-xs px-3 py-1 rounded font-medium transition-colors"
                        >
                          🔄 Recover
                        </button>
                      )}
                    </div>
                  </div>

                  {/* Tab State Info */}
                  {tab.state && (
                    <div className="mt-2 pt-2 border-t border-slate-200">
                      <div className="flex gap-4 text-xs text-slate-600">
                        <span>Form fields: {Object.keys(tab.state.form || {}).length}</span>
                        <span>Snapshots: {tab.state.snapshots?.length || 0}</span>
                        <span>
                          Last update:{' '}
                          {tab.state.snapshots?.[tab.state.snapshots.length - 1]
                            ? new Date(
                                tab.state.snapshots[tab.state.snapshots.length - 1].timestamp
                              ).toLocaleTimeString()
                            : 'N/A'}
                        </span>
                      </div>
                    </div>
                  )}
                </div>
              ))}
            </div>
          </div>
        ) : (
          <div className="text-center py-8">
            <div className="text-4xl mb-3">🔍</div>
            <p className="text-slate-600 font-medium">No other tabs detected</p>
            <p className="text-sm text-slate-400 mt-1">
              Open this app in another tab to see cross-tab synchronization
            </p>
          </div>
        )}

        {/* Info Box */}
        <div className="mt-5 pt-5 border-t border-slate-200">
          <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
            <div className="flex items-start gap-3">
              <div className="text-xl">ℹ️</div>
              <div className="flex-1">
                <p className="text-sm font-semibold text-blue-900 mb-1">
                  Multi-Tab Recovery Active
                </p>
                <p className="text-xs text-blue-700">
                  If one tab crashes, other tabs will detect it and allow you to recover the
                  crashed tab's state. State syncs every 2 seconds across all tabs.
                </p>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Crash Recovery Modal */}
      {showRecoveryModal && crashedTabs.length > 0 && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-2xl shadow-2xl max-w-md w-full p-6 animate-in fade-in zoom-in duration-200">
            <div className="flex items-center gap-3 mb-4">
              <div className="w-12 h-12 bg-red-100 border border-red-200 rounded-xl flex items-center justify-center">
                <span className="text-2xl">⚠️</span>
              </div>
              <div>
                <h3 className="text-xl font-bold text-slate-900">Tab Crashed Detected!</h3>
                <p className="text-sm text-slate-500">
                  {crashedTabs.length} tab{crashedTabs.length > 1 ? 's' : ''} stopped responding
                </p>
              </div>
            </div>

            <div className="bg-red-50 border border-red-200 rounded-lg p-4 mb-4">
              <p className="text-sm text-red-800 mb-3">
                Another tab has crashed and stopped sending heartbeats. You can recover its state
                from this tab.
              </p>

              {crashedTabs.map((tabId) => {
                const tab = otherTabs[tabId];
                return (
                  <div key={tabId} className="bg-white rounded border border-red-200 p-3 mb-2">
                    <div className="flex items-center justify-between mb-2">
                      <span className="text-sm font-mono text-slate-700">{tabId.slice(-8)}</span>
                      <span className="text-xs text-slate-500">
                        Last seen: {getTimeAgo(tab?.lastHeartbeat || 0)}
                      </span>
                    </div>
                    {tab?.state && (
                      <div className="text-xs text-slate-600 mb-2">
                        <strong>Available state:</strong>
                        <ul className="list-disc list-inside mt-1">
                          {Object.entries(tab.state.form || {}).map(([key, value]) => (
                            <li key={key}>
                              {key}: {typeof value === 'string' && value ? '✓ has data' : '(empty)'}
                            </li>
                          ))}
                        </ul>
                      </div>
                    )}
                    <button
                      onClick={() => handleRecover(tabId)}
                      className="w-full bg-red-600 hover:bg-red-700 text-white font-semibold py-2 px-4 rounded transition-colors"
                    >
                      🔄 Recover from This Tab
                    </button>
                  </div>
                );
              })}
            </div>

            <div className="flex gap-3">
              <button
                onClick={() => setShowRecoveryModal(false)}
                className="flex-1 bg-slate-200 hover:bg-slate-300 text-slate-700 font-semibold py-2 px-4 rounded transition-colors"
              >
                Dismiss
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
};
